import java.util.*;
import java.io.*;

public class Main {
    static final int P = 998244353;
    static final int MOD = 1000000007;
    static final int BASE = 1000000;
    static long total = 0;
    static long count = 0;
    static long[] sum = new long[7];
    static int answer = 0;
    static List<Integer>[] p = new ArrayList[7];

    static {
        for (int i = 0; i < 7; i++) {
            p[i] = new ArrayList<>();
        }
    }

    static int mod_value(long d) {
        long res = d % P;
        if (res < 0) res += P;
        return (int) res;
    }

    static void generate_sequences(int depth, long value) {
        total++;
        p[depth].add(mod_value(total - value));
        if (depth < 6) {
            for (int i = 0; i <= 9; i++) {
                generate_sequences(depth + 1, value * 10 + i);
            }
        }
    }

    static int compute(int id, int f) {
        List<Integer> list = p[id];
        int position = lowerBound(list, P - f);
        long res = ((long)f * list.size() + sum[id] - (long)P * (list.size() - position)) % MOD;
        if (res < 0) res += MOD;
        return (int) res;
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    static void explore(int depth, long v) {
        if (v > total) return;
        if (depth >= 1) {
            if (v * BASE > total / 10 && v * BASE + BASE - 1 <= total) {
                int t = 1;
                for (int i = 0; i <= 6; i++) {
                    answer = (answer + compute(i, mod_value(count - v * t))) % MOD;
                    t *= 10;
                }
                for (int i = 0; i <= 6; i++) {
                    count += p[i].size();
                }
                return;
            }
            answer = (answer + mod_value(++count - v)) % MOD;
        }
        for (int i = (depth == 0 ? 1 : 0); i <= 9; i++) {
            explore(depth + 1, v * 10 + i);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n_input = Long.parseLong(br.readLine());
        total = 0;
        generate_sequences(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(p[i]);
            for (int val : p[i]) {
                sum[i] += val;
            }
        }
        count = 0;
        explore(0, 0);
        System.out.println(answer);
    }
}
